// Build a populated mock shipment object ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â stands in for the FedEx API response
const mockShipment=(direction,caseRecord,overrides={})=>{
  const now=toLocalTimestamp();
  const isReturn=direction==="return";
  return {
    ...NULL_SHIPMENT,
    labelStatus:"created",
    trackingNumber:mockTrackingNumber(),
    serviceType:"FEDEX_GROUND",
    carrier:"FedEx",
    createdAt:now,
    createdBy:"Current User",
    recipientName:isReturn?"ITAM Warehouse ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â Charlotte (PTC)":(caseRecord?.userId||""),
    recipientAddress:isReturn?"5765 Flat Rock Rd, Charlotte NC 28217":(caseRecord?.locationId||""),
    shipFromAddress:isReturn?(caseRecord?.locationId||"User Location"):"Charlotte, NC (PTC)",
    weight:"5 lbs",
    masterTrackingNumber:"",
    ...overrides,
  };
};

