const normalizeLocation=(raw)=>{
  if(!raw||!raw.trim())return "\u2014";
  return raw.replace(/- /g,"- ").replace(/\s+/g," ").trim();
};
const normalizeAssetKey=(raw)=>String(raw||"").trim().toUpperCase().replace(/\s+/g," ");
