const parseCSV=(text)=>{
  const rows=[];let row=[];let field="";let inQuote=false;
  for(let i=0;i<text.length;i++){
    const ch=text[i];const next=text[i+1];
    if(inQuote){if(ch==='"'&&next==='"'){field+='"';i++;}else if(ch==='"'){inQuote=false;}else{field+=ch;}}
    else{if(ch==='"'){inQuote=true;}else if(ch===','){row.push(field);field="";}else if(ch==='\r'&&next==='\n'){row.push(field);field="";rows.push(row);row=[];i++;}else if(ch==='\n'){row.push(field);field="";rows.push(row);row=[];}else{field+=ch;}}
  }
  if(field||row.length)row.push(field);if(row.length)rows.push(row);
  return rows;
};
const normalizeCsvHeaderLabel=(value)=>String(value||"")
  .replace(/^\uFEFF/,"")
  .replace(/%23/gi,"#")
  .replace(/[_]+/g," ")
  .replace(/\s+/g," ")
  .trim();
const isSharePointSchemaRow=(row=[])=>{
  const firstCell=row.find(cell=>String(cell||"").trim());
  return /^\s*ListSchema=/i.test(String(firstCell||"").trim());
};
const extractNormalizedCsvTable=(rows,aliasMap={})=>{
  if(!Array.isArray(rows)||rows.length===0)return {headers:[],dataRows:[],headerRowIndex:-1,skippedMetadataRows:0};
  const headerCandidates=new Set(Object.entries(aliasMap).flatMap(([key,aliases])=>[key,...(aliases||[])]).map(normalizeLookupKey));
  let headerRowIndex=-1;
  let bestScore=-1;
  rows.slice(0,12).forEach((row,idx)=>{
    if(isSharePointSchemaRow(row))return;
    const headers=row.map(normalizeCsvHeaderLabel);
    const nonEmpty=headers.filter(Boolean);
    if(nonEmpty.length<2)return;
    const exactMatches=nonEmpty.reduce((sum,header)=>sum+(headerCandidates.has(normalizeLookupKey(header))?1:0),0);
    const heuristicMatches=nonEmpty.reduce((sum,header)=>sum+(/id|name|status|date|time|serial|email|phone|tracking|location|technician|assigned|category|model|asset/i.test(header)?0.25:0),0);
    const score=exactMatches+heuristicMatches;
    if(exactMatches>=2&&score>bestScore){bestScore=score;headerRowIndex=idx;}
  });
  if(headerRowIndex===-1){
    headerRowIndex=rows.findIndex(row=>!isSharePointSchemaRow(row)&&row.some(cell=>String(cell||"").trim()));
  }
  if(headerRowIndex===-1)return {headers:[],dataRows:[],headerRowIndex:-1,skippedMetadataRows:rows.length};
  const headers=rows[headerRowIndex].map(normalizeCsvHeaderLabel);
  const dataRows=rows.slice(headerRowIndex+1).filter(row=>row.some(cell=>String(cell||"").trim()));
  return {headers,dataRows,headerRowIndex,skippedMetadataRows:headerRowIndex};
};

